// Null Radio — a cyber-neon internet radio pane for Claude Code: channel
// dial (synthwave + ambient, hotkeys 1–0), now-playing, a VU, volume,
// stop — the audio itself comes from a LOCAL player the mod spawns and
// kills (ffplay by default; mpv works via the playerPath config).
// /nullradio always opens the dial; /radio too, on builds where
// Anthropic's Claude FM (a gradual-rollout built-in) hasn't claimed it.
//
// Network shape (the house rule): public radio audio comes IN through the
// player's own stream connection; the only other network touches are
// read-only now-playing polls (curl against the stations' public metadata
// endpoints, ffprobe ICY tags for custom channels). Nothing of the session
// ever goes out. Every default channel URL and both metadata endpoints
// were verified live 2026-10-10 from this machine (ffprobe/curl), and the
// exact ffplay argv below was test-fired for 7s against Nightride first.
//
// Lifecycle: the spawn stream IS the child (its loop's end kills it), so a
// hot reload or session end kills the player — never an orphan ffplay.
// session.start auto-resumes when $.state says we were on air, and volume +
// last channel persist across sessions via $.store.
//
// The VU is cosmetic — ffplay exposes no level data; it animates while
// playing (beat-biased random walk), flatlines when stopped.
//
// Hooks swallow their own errors: a bad fetch or a dead player degrades the
// pane (and says so), never the session.
import { atom, read, update } from 'claude-code'
import type { Register } from 'claude-code'

import type { RadioChannel, RadioNowPlaying } from '../types'

const PANE = 'radio'
const VU_COLS = 16
const VU_MS = 400
const META_MS = 20_000
const VOL_STEP = 10

const current = atom({ plugin: 'null-radio', key: 'current' } as const, null)
const isPlaying = atom({ plugin: 'null-radio', key: 'isPlaying' } as const, false)
const volume = atom({ plugin: 'null-radio', key: 'volume' } as const, 70)
const nowPlaying = atom({ plugin: 'null-radio', key: 'nowPlaying' } as const, null)
const vuTick = atom({ plugin: 'null-radio', key: 'vuTick' } as const, 0)
const lastError = atom({ plugin: 'null-radio', key: 'lastError' } as const, null)

const NEON = {
  magenta: '#ff2fd6',
  cyan: '#00e5ff',
  green: '#39ff14',
  yellow: '#ffe600',
  red: '#ff3355',
  violet: '#b86bff',
} as const

// The default dial — every URL verified live 2026-10-10.
const CHANNELS: RadioChannel[] = [
  { id: 'nightride', name: 'Nightride FM', genre: 'synthwave', url: 'https://stream.nightride.fm/nightride.ogg', meta: { kind: 'nightride', station: 'nightride' } },
  { id: 'chillsynth', name: 'ChillSynth FM', genre: 'chill synthwave', url: 'https://stream.nightride.fm/chillsynth.ogg', meta: { kind: 'nightride', station: 'chillsynth' } },
  { id: 'datawave', name: 'DataWave FM', genre: 'downtempo electronics', url: 'https://stream.nightride.fm/datawave.ogg', meta: { kind: 'nightride', station: 'datawave' } },
  { id: 'spacesynth', name: 'SpaceSynth FM', genre: 'space disco', url: 'https://stream.nightride.fm/spacesynth.ogg', meta: { kind: 'nightride', station: 'spacesynth' } },
  { id: 'darksynth', name: 'DarkSynth FM', genre: 'dark / aggressive', url: 'https://stream.nightride.fm/darksynth.ogg', meta: { kind: 'nightride', station: 'darksynth' } },
  { id: 'ebsm', name: 'EBSM', genre: 'industrial dance', url: 'https://stream.nightride.fm/ebsm.ogg', meta: { kind: 'nightride', station: 'ebsm' } },
  { id: 'groovesalad', name: 'Groove Salad', genre: 'ambient beats', url: 'https://ice1.somafm.com/groovesalad-256-mp3', meta: { kind: 'somafm', station: 'groovesalad' } },
  { id: 'dronezone', name: 'Drone Zone', genre: 'deep ambient', url: 'https://ice1.somafm.com/dronezone-256-mp3', meta: { kind: 'somafm', station: 'dronezone' } },
  { id: 'synphaera', name: 'Synphaera', genre: 'space ambient', url: 'https://ice1.somafm.com/synphaera-256-mp3', meta: { kind: 'somafm', station: 'synphaera' } },
  { id: 'defcon', name: 'DEF CON Radio', genre: 'hacker electronica', url: 'https://ice1.somafm.com/defcon-256-mp3', meta: { kind: 'somafm', station: 'defcon' } },
]

// Hotkeys: digits for the first ten rows, then letters — s/p/u/d stay
// reserved for stop / play / vol up / vol down.
const HOTKEYS = '1234567890abcefghijklmnoqrtvwxyz'
const hotkeyFor = (i: number): string | undefined => HOTKEYS[i]

// Module state (lost on hot reload by design — the child dies with the
// module, and $.state carries what matters across).
let channels: RadioChannel[] = [...CHANNELS]
let playerPath = 'ffplay'
let playerGen = 0
let playerStream: AsyncGenerator<{ stream: string; text: string }, unknown> | null = null
let timersStarted = false
let hasRadioCmd = false // /radio registered too? (free unless Claude FM ships here)
let vuLevels: number[] = Array.from({ length: VU_COLS }, () => 0.05)
let vuBeat = 0

const channelById = (id: string | null): RadioChannel | undefined =>
  id === null ? undefined : channels.find(c => c.id === id)

const clip = (s: string, w: number) => (s.length > w ? s.slice(0, Math.max(0, w - 1)) + '…' : s.padEnd(w))

const argvFor = (url: string, vol: number): string[] => {
  const p = playerPath.toLowerCase()
  if (p.includes('mpv')) return [playerPath, '--no-video', '--really-quiet', `--volume=${vol}`, url]
  // ffplay: flags test-fired 2026-10-10 — no window, quiet, auto-reconnect.
  return [
    playerPath, '-hide_banner', '-nodisp', '-loglevel', 'error', '-nostats',
    '-volume', String(vol),
    '-reconnect', '1', '-reconnect_streamed', '1', '-reconnect_delay_max', '5',
    url,
  ]
}

// ---- now-playing parsers (each endpoint's shape verified live 2026-10-10) ----

// Nightride serves one SSE feed for ALL its stations:
//   data: [{"station":"nightride","title":"...","artist":"..."}]
// A ~4s curl grab catches the full roster's current tracks.
const parseNightride = (stdout: string, station: string): RadioNowPlaying | null => {
  let found: RadioNowPlaying | null = null
  for (const line of stdout.split('\n')) {
    if (!line.startsWith('data:')) continue
    try {
      const rows = JSON.parse(line.slice(5).trim()) as Array<{ station?: string; title?: string; artist?: string }>
      if (!Array.isArray(rows)) continue
      for (const r of rows) {
        if (r.station === station && (r.title ?? '') !== '') found = { artist: r.artist ?? '', title: r.title ?? '' }
      }
    } catch {}
  }
  return found
}

// SomaFM: https://somafm.com/songs/<station>.json — songs[0] is current.
const parseSomafm = (stdout: string): RadioNowPlaying | null => {
  try {
    const j = JSON.parse(stdout) as { songs?: Array<{ title?: string; artist?: string }> }
    const s = j.songs?.[0]
    if (s === undefined || ((s.title ?? '') === '' && (s.artist ?? '') === '')) return null
    return { artist: s.artist ?? '', title: s.title ?? '' }
  } catch {
    return null
  }
}

// ICY fallback for custom channels: ffprobe reads StreamTitle off the
// stream itself ("Artist - Title" by convention).
const parseIcy = (stdout: string): RadioNowPlaying | null => {
  const t = stdout.split('\n')[0]?.trim() ?? ''
  if (t === '') return null
  const cut = t.indexOf(' - ')
  return cut < 0 ? { artist: '', title: t } : { artist: t.slice(0, cut), title: t.slice(cut + 3) }
}

async function fetchNowPlaying($: any, ch: RadioChannel) {
  try {
    let np: RadioNowPlaying | null = null
    if (ch.meta.kind === 'nightride') {
      // curl exits 28 when --max-time cuts the SSE feed — the data is in
      // stdout regardless, so the exit code is ignored on purpose.
      const r = await $.process.run(['curl', '-s', '-N', '--max-time', '4', 'https://nightride.fm/meta'], { timeoutMs: 9000 })
      np = parseNightride(String(r.stdout ?? ''), ch.meta.station)
    } else if (ch.meta.kind === 'somafm') {
      const r = await $.process.run(['curl', '-s', '--max-time', '6', `https://somafm.com/songs/${ch.meta.station}.json`], { timeoutMs: 9000 })
      np = parseSomafm(String(r.stdout ?? ''))
    } else if (ch.meta.kind === 'icy') {
      const r = await $.process.run(
        ['ffprobe', '-v', 'error', '-rw_timeout', '6000000', '-show_entries', 'format_tags=StreamTitle', '-of', 'default=noprint_wrappers=1:nokey=1', ch.url],
        { timeoutMs: 12000 },
      )
      np = parseIcy(String(r.stdout ?? ''))
    } else {
      return
    }
    if (np === null) return
    // The dial may have moved while the fetch ran.
    if ((await read($, current)) !== ch.id || !(await read($, isPlaying))) return
    const prev = (await read($, nowPlaying)) as RadioNowPlaying | null
    if (prev !== null && prev.artist === np.artist && prev.title === np.title) return
    await update($, nowPlaying, () => np)
    try {
      const line = np.artist === '' ? np.title : `${np.artist} — ${np.title}`
      $.ui.status(`♪ ${clip(line, 70).trimEnd()} · ${ch.name}`)
    } catch {}
  } catch {}
}

// ---- the player itself ----

function stopProcess() {
  playerGen++ // marks any running drain loop as "replaced on purpose"
  const s = playerStream
  playerStream = null
  if (s !== null) {
    try {
      void (s.return(undefined as never) as Promise<unknown>).catch(() => {})
    } catch {}
  }
}

async function drain($: any, stream: AsyncGenerator<{ stream: string; text: string }, unknown>, g: number, ch: RadioChannel) {
  let tail = ''
  let failed = ''
  try {
    for await (const chunk of stream) {
      if (chunk.stream === 'stderr') tail = (tail + chunk.text).slice(-300)
      // Pace the pulls: ffplay is near-silent at -loglevel error, so this
      // loop normally parks on the first pull until the child exits.
      try {
        await $.clock.sleep(200)
      } catch {}
    }
  } catch (err) {
    failed = String(err) // the child could not start (first pull rejects)
  }
  if (playerGen !== g) return // we stopped or retuned it ourselves
  playerStream = null
  try {
    const why = (tail.trim() !== '' ? tail.trim() : failed !== '' ? failed : 'player exited').slice(-160)
    await update($, isPlaying, () => false)
    await update($, lastError, () => why)
    $.ui.status(undefined)
    $.ui.toast(`📻 ${ch.name} stopped — ${why.slice(0, 90)}`)
  } catch {}
}

async function startPlayback($: any, ch: RadioChannel) {
  try {
    if ((await read($, isPlaying)) && (await read($, current)) === ch.id && playerStream !== null) return
    stopProcess()
    const g = ++playerGen
    const vol = (await read($, volume)) as number
    await update($, current, () => ch.id)
    await update($, isPlaying, () => true)
    await update($, lastError, () => null)
    await update($, nowPlaying, () => null)
    try {
      await $.store.set('lastChannel', ch.id)
    } catch {}
    try {
      $.ui.status(`♪ ${ch.name}`)
    } catch {}
    const stream = $.process.spawn({ argv: argvFor(ch.url, vol) })
    playerStream = stream
    void drain($, stream, g, ch)
    void fetchNowPlaying($, ch)
  } catch {}
}

async function stopPlayback($: any) {
  try {
    stopProcess()
    await update($, isPlaying, () => false)
    await update($, nowPlaying, () => null)
    try {
      $.ui.status(undefined)
    } catch {}
  } catch {}
}

// Volume lands by respawning the player at the new level (ffplay takes
// volume only at launch) — a sub-second gap in the audio, by design.
async function setVolume($: any, delta: number) {
  try {
    let v = 70
    await update($, volume, old => {
      v = Math.max(0, Math.min(100, (old as number) + delta))
      return v
    })
    try {
      await $.store.set('volume', v)
    } catch {}
    if ((await read($, isPlaying)) === true) {
      const ch = channelById((await read($, current)) as string | null)
      if (ch !== undefined) {
        playerGen++ // retune on purpose: keep drain quiet about the swap
        await startPlaybackFresh($, ch)
      }
    }
  } catch {}
}

// startPlayback skips when the same channel is already on air; a volume
// change needs the respawn anyway, so it goes around that guard.
async function startPlaybackFresh($: any, ch: RadioChannel) {
  stopProcess()
  const g = ++playerGen
  const vol = (await read($, volume)) as number
  const stream = $.process.spawn({ argv: argvFor(ch.url, vol) })
  playerStream = stream
  void drain($, stream, g, ch)
}

async function openDial($: any) {
  await $.ui.open({ id: PANE, title: 'Null Radio' })
  const playing = (await read($, isPlaying)) === true
  const ch = channelById((await read($, current)) as string | null)
  return {
    text:
      playing && ch !== undefined
        ? `Null Radio opened — on air: ${ch.name}.`
        : 'Null Radio opened — pick a channel (hotkeys 1–0 when the pane is focused).',
  }
}

// ---- cosmetic VU ----

const VU_GLYPHS = '▁▂▃▄▅▆▇█'
const vuGlyph = (l: number) => VU_GLYPHS[Math.min(7, Math.max(0, Math.floor(l * 8)))] ?? '▁'
const vuColor = (l: number) => (l < 0.45 ? NEON.cyan : l < 0.75 ? NEON.violet : NEON.magenta)

function vuAdvance() {
  vuBeat = (vuBeat + 1) % 8
  const pulse = vuBeat < 2 ? 0.3 : 0
  const half = (VU_COLS - 1) / 2
  for (let i = 0; i < VU_COLS; i++) {
    const centerBias = (1 - Math.abs(i - half) / half) * 0.3
    const target = Math.random() * 0.5 + pulse + centerBias
    vuLevels[i] = Math.max(0.04, Math.min(1, (vuLevels[i] ?? 0.05) * 0.55 + target * 0.45))
  }
}

// ---- wiring ----

export const register: Register = (on, options) => {
  playerPath = ((options as { playerPath?: string } | undefined)?.playerPath ?? 'ffplay').trim() || 'ffplay'
  channels = [...CHANNELS]
  try {
    const raw = (options as { extraChannels?: string } | undefined)?.extraChannels
    if (typeof raw === 'string' && raw.trim() !== '') {
      const rows = JSON.parse(raw) as Array<Partial<RadioChannel>>
      if (Array.isArray(rows)) {
        for (const r of rows) {
          if (typeof r.id === 'string' && typeof r.name === 'string' && typeof r.url === 'string' && channelById(r.id) === undefined) {
            channels.push({
              id: r.id,
              name: r.name,
              url: r.url,
              genre: typeof r.genre === 'string' ? r.genre : 'custom',
              meta: r.meta !== undefined && typeof r.meta === 'object' ? (r.meta as RadioChannel['meta']) : { kind: 'icy' },
            })
          }
        }
      }
    }
  } catch {}

  on('session.start', async ($, e, next) => {
    try {
      // /nullradio is the stable name, registered always; /radio is the
      // convenience alias, taken where Anthropic's Claude FM built-in (a
      // gradual rollout) hasn't claimed it — refused there, by design.
      try {
        await $.command.register({ name: 'nullradio', description: 'Null Radio: open the cyber-neon dial' })
      } catch {}
      try {
        await $.command.register({ name: 'radio', description: 'Null Radio: open the cyber-neon dial' })
        hasRadioCmd = true
      } catch {}
      try {
        const sv = await $.store.get('volume')
        if (typeof sv === 'number' && Number.isFinite(sv)) await update($, volume, () => Math.max(0, Math.min(100, Math.round(sv))))
        const sc = await $.store.get('lastChannel')
        if (typeof sc === 'string' && channelById(sc) !== undefined) await update($, current, c => c ?? sc)
      } catch {}
      // A hot reload killed the child with the old module; state remembers
      // we were on air, so the music comes back by itself.
      if ((await read($, isPlaying)) === true) {
        const ch = channelById((await read($, current)) as string | null)
        if (ch !== undefined) await startPlayback($, ch)
        else await update($, isPlaying, () => false)
      }
      if (!timersStarted) {
        timersStarted = true
        $.clock.every(VU_MS, async () => {
          try {
            if ((await read($, isPlaying)) !== true) return
            vuAdvance()
            await update($, vuTick, t => ((t as number) + 1) % 1_000_000)
          } catch {}
        })
        $.clock.every(META_MS, async () => {
          try {
            if ((await read($, isPlaying)) !== true) return
            const ch = channelById((await read($, current)) as string | null)
            if (ch !== undefined) await fetchNowPlaying($, ch)
          } catch {}
        })
      }
    } catch {}
    return next(e)
  })

  // /nullradio is always ours; /radio answers only when this module owns
  // it, and otherwise passes down the chain (a built-in Claude FM) untouched.
  on('command.run', { command: 'nullradio' }, async $ => openDial($))
  on('command.run', { command: 'radio' }, async ($, e, next) => (hasRadioCmd ? openDial($) : next(e))).catch(($, e, next) => next(e))

  on('ui.render', { component: 'Pane', requestId: PANE }, async ($, e) => {
    const { Box, Text, Button } = $.ui.resolve(e)
    try {
      const playing = (await read($, isPlaying)) === true
      const curId = (await read($, current)) as string | null
      const vol = (await read($, volume)) as number
      const np = (await read($, nowPlaying)) as RadioNowPlaying | null
      const err = (await read($, lastError)) as string | null
      await read($, vuTick) // subscribes the pane to the VU animation clock

      const body = e.props.bodyColumns ?? e.viewport?.columns ?? 60
      const nameW = Math.max(12, Math.min(18, body - 30))
      const genreW = Math.max(8, Math.min(22, body - nameW - 10))

      // One Text per same-color run keeps the tree small.
      const vuRuns: Array<{ text: string; color: string }> = []
      for (const l of vuLevels) {
        const color = vuColor(l)
        const g = vuGlyph(l)
        const last = vuRuns[vuRuns.length - 1]
        if (last !== undefined && last.color === color) last.text += g
        else vuRuns.push({ text: g, color })
      }

      return (
        <Box flexDirection="column">
          <Box>
            <Text color={NEON.magenta} bold>
              ▚▞ NULL RADIO{'  '}
            </Text>
            {playing ? <Text color={NEON.green}>● ON AIR</Text> : <Text dimColor>○ off air</Text>}
            <Text dimColor> · vol {String(vol)}</Text>
          </Box>
          <Box>
            {playing ? (
              vuRuns.map((r, i) => (
                <Text key={'vu' + String(i)} color={r.color}>
                  {r.text}
                </Text>
              ))
            ) : (
              <Text dimColor>{'▁'.repeat(VU_COLS)}</Text>
            )}
          </Box>
          {np !== null ? (
            <Box>
              <Text color={NEON.cyan} wrap="truncate-end">
                ♪ {np.title}
              </Text>
              {np.artist !== '' ? <Text color={NEON.violet} wrap="truncate-end">{'  '}{np.artist}</Text> : null}
            </Box>
          ) : playing ? (
            <Text dimColor>♪ tuning…</Text>
          ) : null}
          <Text dimColor>── dial ─────────────</Text>
          {channels.map((ch, i) => {
            const isCur = curId === ch.id
            return (
              <Box key={ch.id}>
                <Button key={'ch-' + ch.id} plain hotkey={hotkeyFor(i)} onPress={() => void startPlayback($, ch)}>
                  {isCur && playing ? (
                    <Text color={NEON.magenta} bold>
                      ▸ {clip(ch.name, nameW)}
                    </Text>
                  ) : isCur ? (
                    <Text color={NEON.violet}>▹ {clip(ch.name, nameW)}</Text>
                  ) : (
                    <Text color={NEON.cyan}>{'  '}{clip(ch.name, nameW)}</Text>
                  )}
                  <Text dimColor> {clip(ch.genre, genreW)}</Text>
                </Button>
              </Box>
            )
          })}
          <Box>
            {playing ? (
              <Button key="stop" plain hotkey="s" onPress={() => void stopPlayback($)}>
                <Text color={NEON.red}>■ stop</Text>
              </Button>
            ) : curId !== null ? (
              <Button key="play" plain hotkey="p" onPress={() => {
                const ch = channelById(curId)
                if (ch !== undefined) void startPlayback($, ch)
              }}>
                <Text color={NEON.green}>▶ play</Text>
              </Button>
            ) : null}
            <Text> </Text>
            <Button key="vol-down" plain hotkey="d" onPress={() => void setVolume($, -VOL_STEP)}>
              <Text color={NEON.yellow}>vol−</Text>
            </Button>
            <Text> </Text>
            <Button key="vol-up" plain hotkey="u" onPress={() => void setVolume($, VOL_STEP)}>
              <Text color={NEON.yellow}>vol+</Text>
            </Button>
          </Box>
          {err !== null ? (
            <Text color={NEON.red} wrap="truncate-end">
              ⚠ {err}
            </Text>
          ) : null}
          <Text dimColor>1–0 tune · s stop · u/d vol · /{hasRadioCmd ? 'radio' : 'nullradio'} reopens</Text>
        </Box>
      )
    } catch {
      return <Text dimColor>null-radio: render error (the pane will recover next redraw)</Text>
    }
  })
}

