export type RadioNowPlaying = { artist: string; title: string }

export type RadioMeta =
  | { kind: 'nightride'; station: string }
  | { kind: 'somafm'; station: string }
  | { kind: 'icy' }
  | { kind: 'none' }

export type RadioChannel = {
  id: string
  name: string
  genre: string
  url: string
  meta: RadioMeta
}

declare module 'claude-code' {
  interface PluginState {
    'null-radio': {
      current: string | null
      isPlaying: boolean
      volume: number
      nowPlaying: RadioNowPlaying | null
      vuTick: number
      lastError: string | null
    }
  }
}
